let overVolt = flow.get('Pras1XlimitOverVolt')
let underVolt = flow.get('Pras1XlimitUnderVolt')

msg.payload = {
    area:"Terminal Petikemas Semarang",
    lokasi:"prasasti_1",
    data:{
        request: atRequest,
        device: motorName,
        passdecode: decode,
        mode: controllerMode,
        ultrasonic: waterLevel,
        statusPump1: pump1,
