        warningMaintainAge: maintainAge,
        nominalPower: nomPower,
        nominalCurrent: nomCurrent,
        realPower:realPower,

        overCurrentLimit: overCurrent,
        overVoltageLimit: overVolt,
        underVoltageLimit: underVolt,
    }
};
return msg;

