//binary data cek berdasarkan no array pompa
function cekBinary(str,no) {
    let cek = ''
    for (let i=0; i<str.length; i++) {
        if(str[no]==1){
          cek="ON"
        }
        else {cek="OFF"}
    }
    return cek
}
