function decimalArrayToHexArray(decimalArray) {
    return decimalArray.map(decimal => decimal.toString(16).padStart(4, "0"))
}

// fungsi heksadesimal ke tanggal
function hex2Date(str) {
   let tx=str.join('');
   let tx1=tx.substr(0,2)
   let tx2=tx.substr(2,2)
   let tx3=tx.substr(4,2)
   return tx="20"+tx3+"-"+tx2+"-"+tx1
}

